INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Aufgabenanalyse nur für komplexe Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für einfache Aufgaben nützlich"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Aufgabenanalyse?', 3, '[{"text": "Aufgaben strukturieren", "correct": true, "because": "Zerlegung in Teilaufgaben"}, {"text": "Kosten senken", "correct": false, "because": "Indirekter Effekt"}, {"text": "Design verbessern", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Aufgabenanalyse?', 5, '[{"text": "Zerlegung in Teilaufgaben", "correct": true, "because": "Kern der Analyse"}, {"text": "Reihenfolge festlegen", "correct": true, "because": "Definiert Ablauf"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aufgabenanalyse verbessert die Planung. b) Sie ist immer zeitaufwendig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeitaufwand variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Aufgabenanalyse?', 4, '[{"text": "Aufgabenkomplexität", "correct": false, "because": "Entscheidend für Zerlegung"}, {"text": "Ressourcenbedarf", "correct": false, "because": "Wichtig für Planung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Aufgabenanalyse Prioritäten setzt?', 2, '[{"text": "Ja", "correct": true, "because": "Reihenfolge und Wichtigkeit"}, {"text": "Nein", "correct": false, "because": "Häufig enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine Aufgabenanalyse?', 3, '[{"text": "Hierarchische Zerlegung", "correct": true, "because": "Strukturierte Teilung"}, {"text": "Zufällige Aufteilung", "correct": false, "because": "Unstrukturiert"}, {"text": "Marketinganalyse", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Durchführung einer Aufgabenanalyse?', 5, '[{"text": "Identifikation von Teilaufgaben", "correct": true, "because": "Grundschritt"}, {"text": "Abhängigkeiten erkennen", "correct": true, "because": "Definiert Reihenfolge"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Aufgabenanalyse erleichtert die Koordination. b) Sie ist nur für Teams nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Einzelpersonen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Aufgabenanalyse unwichtig?', 4, '[{"text": "Aufgabenstruktur", "correct": false, "because": "Kern der Analyse"}, {"text": "Ressourcenzuweisung", "correct": false, "because": "Wichtig für Umsetzung"}, {"text": "Bürofarben", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Aufgabenanalyse statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassbar an Änderungen"}, {"text": "Ja", "correct": false, "because": "Dynamisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine Aufgabenanalyse?', 4, '[{"text": "Klare Struktur", "correct": true, "because": "Übersicht verbessert"}, {"text": "Effiziente Planung", "correct": true, "because": "Ressourcen optimiert"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Aufgabenanalyse nur für Projektmanagement ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Alltag"}, {"text": "Ja", "correct": false, "because": "Breiter anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Aufgabenanalyse?', 3, '[{"text": "Aufgabenzerlegung", "correct": true, "because": "Kern der Methode"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aufgabenanalyse identifiziert Abhängigkeiten. b) Sie ist immer schriftlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann mündlich sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Aufgabenanalyse?', 5, '[{"text": "Unklare Prioritäten", "correct": true, "because": "Fehlende Struktur"}, {"text": "Ineffiziente Arbeit", "correct": true, "because": "Ressourcenverschwendung"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Aufgabenanalyse unwichtig?', 3, '[{"text": "Teilaufgaben", "correct": false, "because": "Kernbestandteil"}, {"text": "Abhängigkeiten", "correct": false, "because": "Definiert Ablauf"}, {"text": "Teamuniformen", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Aufgabenanalyse Ressourcen zuweisen?', 3, '[{"text": "Ja", "correct": true, "because": "Planung enthalten"}, {"text": "Nein", "correct": false, "because": "Häufig Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Aufgabenanalyse Zeitpläne umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Oft Teil der Analyse"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine Aufgabenanalyse?', 4, '[{"text": "Work Breakdown Structure", "correct": true, "because": "Hierarchische Zerlegung"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}, {"text": "Werbekampagne", "correct": false, "because": "Kein Bezug"}]');
